// Builds a three.js scene from a world's part list. Shared by the game
// client, studio editor and avatar preview. Everything is primitives and
// generated canvas textures — zero asset files.
import * as THREE from 'three';

export const SOLID_TYPES = new Set(['block', 'spawn', 'checkpoint', 'goal', 'bounce', 'speed', 'mover', 'tele', 'kill']);

export function setupScene(canvas) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x7ec8e8);
  scene.fog = new THREE.Fog(0x7ec8e8, 120, 420);

  const sun = new THREE.DirectionalLight(0xfff4e0, 2.2);
  sun.position.set(60, 110, 40);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  const sc = sun.shadow.camera;
  sc.left = -90; sc.right = 90; sc.top = 90; sc.bottom = -90; sc.far = 320;
  scene.add(sun);
  scene.add(sun.target); // so the light can track the player
  scene.add(new THREE.AmbientLight(0xbfd9e8, 1.1));
  const hemi = new THREE.HemisphereLight(0xcfeaff, 0x4a6b50, 0.5);
  scene.add(hemi);

  const camera = new THREE.PerspectiveCamera(70, 1, 0.1, 1200);
  camera.position.set(10, 10, 10);

  function resize() {
    const w = canvas.clientWidth, h = canvas.clientHeight;
    if (canvas.width !== Math.floor(w * renderer.getPixelRatio()) || canvas.height !== Math.floor(h * renderer.getPixelRatio())) {
      renderer.setSize(w, h, false);
      camera.aspect = w / Math.max(1, h);
      camera.updateProjectionMatrix();
    }
  }
  return { renderer, scene, camera, sun, resize };
}

// ---------- procedural textures (generated once, shared) ----------
function canvasTex(w, h, draw) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

let _tex = null;
function tex() {
  if (_tex) return _tex;
  _tex = {
    // classic building-block stud, multiplied with part color
    stud: canvasTex(64, 64, (ctx, w, h) => {
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = 'rgba(0,0,0,0.13)';
      ctx.lineWidth = 4;
      ctx.beginPath(); ctx.arc(w / 2, h / 2, 15, 0, 7); ctx.stroke();
      ctx.fillStyle = 'rgba(255,255,255,0.5)';
      ctx.beginPath(); ctx.arc(w / 2 - 3, h / 2 - 3, 12, 0, 7); ctx.fill();
      ctx.fillStyle = 'rgba(0,0,0,0.07)';
      ctx.beginPath(); ctx.arc(w / 2 + 2, h / 2 + 2, 13, 0, 7); ctx.fill();
    }),
    // diagonal hazard stripes for kill bricks
    hazard: canvasTex(64, 64, (ctx, w, h) => {
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 13;
      for (let i = -2; i < 5; i++) {
        ctx.beginPath();
        ctx.moveTo(i * 32 - 16, h + 8);
        ctx.lineTo(i * 32 + h - 16, -8);
        ctx.stroke();
      }
    }),
    // chevrons for speed pads (scrolled at runtime)
    chevron: canvasTex(64, 64, (ctx, w, h) => {
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = 'rgba(0,0,0,0.45)';
      ctx.lineWidth = 9;
      ctx.lineCap = 'round';
      for (const y of [14, 46]) {
        ctx.beginPath();
        ctx.moveTo(12, y + 10);
        ctx.lineTo(32, y - 10);
        ctx.lineTo(52, y + 10);
        ctx.stroke();
      }
    }),
    // soft ripple rings for water (scrolled at runtime)
    wave: canvasTex(64, 64, (ctx, w, h) => {
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = 'rgba(255,255,255,0.0)';
      ctx.fillStyle = 'rgba(0,0,30,0.12)';
      for (let i = 0; i < 5; i++) {
        ctx.beginPath();
        ctx.ellipse((i * 23) % w, (i * 41 + 12) % h, 14, 5, 0.4, 0, 7);
        ctx.fill();
      }
      ctx.fillStyle = 'rgba(255,255,255,0.35)';
      for (let i = 0; i < 5; i++) {
        ctx.beginPath();
        ctx.ellipse((i * 29 + 8) % w, (i * 17 + 30) % h, 10, 3.5, -0.3, 0, 7);
        ctx.fill();
      }
    }),
    // soft round cloud sprite
    cloud: (() => {
      const c = document.createElement('canvas');
      c.width = 128; c.height = 64;
      const ctx = c.getContext('2d');
      for (const [x, y, r] of [[36, 40, 20], [64, 32, 26], [92, 42, 18], [56, 46, 22]]) {
        const g = ctx.createRadialGradient(x, y, 2, x, y, r);
        g.addColorStop(0, 'rgba(255,255,255,0.85)');
        g.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.fillStyle = g;
        ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
      }
      const t = new THREE.CanvasTexture(c);
      t.colorSpace = THREE.SRGBColorSpace;
      return t;
    })(),
  };
  return _tex;
}

// ---------- shared geometries ----------
const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const boxEdges = new THREE.EdgesGeometry(boxGeo);
const edgeMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.16 });
const coinBody = new THREE.CylinderGeometry(0.5, 0.5, 0.14, 24);
coinBody.rotateX(Math.PI / 2);
const coinRim = new THREE.TorusGeometry(0.5, 0.075, 10, 26);

function std(opts) { return new THREE.MeshStandardMaterial(opts); }

// Scaled box with optional stud-top + edge outline. Top face = material idx 2.
function detailBox(part, sideMat, topTexture, edges = true) {
  let mesh;
  if (topTexture) {
    const map = topTexture.clone();
    map.needsUpdate = true;
    map.repeat.set(Math.max(1, Math.round(part.sx)), Math.max(1, Math.round(part.sz)));
    const topMat = sideMat.clone();
    topMat.map = map;
    mesh = new THREE.Mesh(boxGeo, [sideMat, sideMat, topMat, sideMat, sideMat, sideMat]);
  } else {
    mesh = new THREE.Mesh(boxGeo, sideMat);
  }
  mesh.scale.set(part.sx, part.sy, part.sz);
  if (edges) {
    const line = new THREE.LineSegments(boxEdges, edgeMat);
    mesh.add(line);
  }
  return mesh;
}

export function createPartMesh(part) {
  const T = tex();
  const color = new THREE.Color(part.color || '#aaaaaa');
  const group = new THREE.Group();
  let main = null;       // the box that visualizes the collision volume
  let animFn = null;     // per-frame decoration animation

  switch (part.type) {
    case 'coin': {
      const gold = std({ color: 0xffd700, metalness: 0.75, roughness: 0.22, emissive: 0x6b5200 });
      const body = new THREE.Mesh(coinBody, gold);
      const rim = new THREE.Mesh(coinRim, std({ color: 0xffe680, metalness: 0.8, roughness: 0.18, emissive: 0x705a00 }));
      const gem = new THREE.Mesh(new THREE.OctahedronGeometry(0.22), std({ color: 0xfff3b0, emissive: 0x8a6d00, metalness: 0.6, roughness: 0.2 }));
      gem.position.z = 0; gem.scale.z = 0.45;
      group.add(body, rim, gem);
      break;
    }
    case 'water': {
      const map = T.wave.clone(); map.needsUpdate = true;
      map.repeat.set(Math.max(1, part.sx / 4), Math.max(1, part.sz / 4));
      main = new THREE.Mesh(boxGeo, std({ color, transparent: true, opacity: 0.58, roughness: 0.1, metalness: 0.15, map }));
      main.scale.set(part.sx, part.sy, part.sz);
      animFn = (t) => { map.offset.set(t * 0.02 % 1, t * 0.013 % 1); };
      group.add(main);
      break;
    }
    case 'kill': {
      main = detailBox(part, std({ color: 0xd40000, emissive: 0x500000, roughness: 0.4 }), T.hazard);
      // menacing little spikes along the top
      const spikeMat = std({ color: 0x8c0000, roughness: 0.35, metalness: 0.3 });
      const n = Math.min(6, Math.max(2, Math.round(part.sx / 2)));
      for (let i = 0; i < n; i++) {
        const s = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.42, 4), spikeMat);
        s.position.set(-part.sx / 2 + (i + 0.5) * (part.sx / n), part.sy / 2 + 0.21, 0);
        group.add(s);
      }
      group.add(main);
      break;
    }
    case 'goal': {
      main = detailBox(part, std({ color: 0x19ff8c, emissive: 0x0a6b3a, roughness: 0.3 }), T.stud);
      // glowing victory arch
      const archMat = std({ color: 0xbfffd0, emissive: 0x19ff8c, emissiveIntensity: 0.8, roughness: 0.2 });
      const r = Math.min(part.sx, part.sz) * 0.42;
      const arch = new THREE.Mesh(new THREE.TorusGeometry(r, 0.12, 10, 30, Math.PI), archMat);
      arch.position.y = part.sy / 2;
      group.add(arch);
      animFn = (t) => { archMat.emissiveIntensity = 0.65 + Math.sin(t * 3) * 0.35; };
      group.add(main);
      break;
    }
    case 'checkpoint': {
      main = detailBox(part, std({ color: 0x19c2ff, emissive: 0x05435e, roughness: 0.3 }), T.stud);
      // little flag on a pole
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 1.6, 8), std({ color: 0xe8eef2, roughness: 0.4, metalness: 0.5 }));
      pole.position.set(part.sx / 2 - 0.3, part.sy / 2 + 0.8, part.sz / 2 - 0.3);
      const flagMat = std({ color: 0x19c2ff, emissive: 0x0a4a66, side: THREE.DoubleSide });
      const flag = new THREE.Mesh(new THREE.PlaneGeometry(0.62, 0.4), flagMat);
      flag.position.set(pole.position.x - 0.33, pole.position.y + 0.5, pole.position.z);
      group.add(pole, flag);
      animFn = (t) => { flag.rotation.y = Math.sin(t * 2.2) * 0.3; };
      group.add(main);
      break;
    }
    case 'bounce': {
      main = detailBox(part, std({ color: 0xffe14d, emissive: 0x4d3f00, roughness: 0.35 }), T.stud);
      // visible spring coil under a cap
      const coilMat = std({ color: 0x999aa6, metalness: 0.75, roughness: 0.3 });
      const r = Math.min(part.sx, part.sz) * 0.28;
      for (let i = 0; i < 3; i++) {
        const ring = new THREE.Mesh(new THREE.TorusGeometry(r - i * 0.05, 0.06, 8, 20), coilMat);
        ring.rotation.x = Math.PI / 2;
        ring.position.y = part.sy / 2 + 0.1 + i * 0.13;
        group.add(ring);
      }
      const cap = new THREE.Mesh(new THREE.CylinderGeometry(r + 0.12, r + 0.12, 0.1, 20), std({ color: 0xffe14d, emissive: 0x4d3f00 }));
      cap.position.y = part.sy / 2 + 0.52;
      group.add(cap);
      animFn = (t) => { cap.position.y = part.sy / 2 + 0.52 + Math.abs(Math.sin(t * 2.4)) * 0.1; };
      group.add(main);
      break;
    }
    case 'speed': {
      const map = T.chevron.clone(); map.needsUpdate = true;
      map.repeat.set(Math.max(1, Math.round(part.sx / 2)), Math.max(1, Math.round(part.sz / 2)));
      const baseMat = std({ color: 0x19c2ff, emissive: 0x0a4a5e, roughness: 0.2, metalness: 0.3 });
      const topMat = baseMat.clone(); topMat.map = map;
      main = new THREE.Mesh(boxGeo, [baseMat, baseMat, topMat, baseMat, baseMat, baseMat]);
      main.scale.set(part.sx, part.sy, part.sz);
      main.add(new THREE.LineSegments(boxEdges, edgeMat));
      animFn = (t) => { map.offset.y = (-t * 0.9) % 1; };
      group.add(main);
      break;
    }
    case 'tele': {
      main = detailBox(part, std({ color: 0x8a4fff, emissive: 0x2d1466, roughness: 0.3 }), T.stud);
      // orbiting energy orbs
      const orbMat = std({ color: 0xd9c4ff, emissive: 0x8a4fff, emissiveIntensity: 1.1, roughness: 0.2 });
      const swirl = new THREE.Group();
      const r = Math.min(part.sx, part.sz) * 0.36;
      for (let i = 0; i < 3; i++) {
        const orb = new THREE.Mesh(new THREE.SphereGeometry(0.11, 10, 8), orbMat);
        const a = (i / 3) * Math.PI * 2;
        orb.position.set(Math.cos(a) * r, 0.45 + i * 0.28, Math.sin(a) * r);
        swirl.add(orb);
      }
      swirl.position.y = part.sy / 2;
      group.add(swirl);
      animFn = (t) => { swirl.rotation.y = t * 2.2; };
      group.add(main);
      break;
    }
    case 'spawn': {
      main = detailBox(part, std({ color, roughness: 0.7 }), T.stud);
      const ringMat = std({ color: 0xbfeaff, emissive: 0x19c2ff, emissiveIntensity: 0.7, roughness: 0.25 });
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(Math.min(part.sx, part.sz) * 0.4, 0.07, 8, 28), ringMat);
      ring.rotation.x = Math.PI / 2;
      ring.position.y = part.sy / 2 + 0.05;
      group.add(ring);
      animFn = (t) => { ringMat.emissiveIntensity = 0.5 + Math.sin(t * 2) * 0.3; };
      group.add(main);
      break;
    }
    case 'deco': {
      main = detailBox(part, std({ color, roughness: 0.8 }), null);
      group.add(main);
      break;
    }
    default: { // block, mover
      const mat = part.type === 'mover'
        ? std({ color, roughness: 0.5, metalness: 0.25, emissive: color.clone().multiplyScalar(0.12) })
        : std({ color, roughness: 0.85 });
      main = detailBox(part, mat, T.stud);
      group.add(main);
    }
  }

  group.position.set(part.x, part.y, part.z);
  group.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = part.sx * part.sz < 2000 && part.type !== 'water';
      o.receiveShadow = part.type !== 'water';
    }
  });
  group.userData.part = part;
  if (animFn) group.userData.animFn = animFn;
  return group;
}

export class World {
  constructor(scene) {
    this.scene = scene;
    this.group = new THREE.Group();
    scene.add(this.group);
    this.meshes = new Map(); // partId -> mesh group
    this.parts = new Map();  // partId -> part
    this.timeOffset = 0;     // serverTime - clientNow, for synced movers
    this._addClouds();
  }

  _addClouds() {
    this.clouds = new THREE.Group();
    const mat = new THREE.SpriteMaterial({ map: tex().cloud, transparent: true, opacity: 0.85, depthWrite: false });
    let seed = 987654;
    const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    for (let i = 0; i < 10; i++) {
      const s = new THREE.Sprite(mat);
      const scale = 26 + rnd() * 34;
      s.scale.set(scale, scale * 0.5, 1);
      s.position.set((rnd() - 0.5) * 380, 60 + rnd() * 70, (rnd() - 0.5) * 380);
      s.userData.speed = 0.4 + rnd() * 0.8;
      this.clouds.add(s);
    }
    this.scene.add(this.clouds);
  }

  load(parts) {
    for (const m of this.meshes.values()) this.group.remove(m);
    this.meshes.clear();
    this.parts.clear();
    for (const p of parts) this.addPart(p);
  }

  addPart(part) {
    this.removePart(part.id);
    const mesh = createPartMesh(part);
    this.group.add(mesh);
    this.meshes.set(part.id, mesh);
    this.parts.set(part.id, part);
    return mesh;
  }

  removePart(id) {
    const m = this.meshes.get(id);
    if (m) {
      this.group.remove(m);
      this.meshes.delete(id);
      this.parts.delete(id);
    }
  }

  serverNow() {
    return Date.now() + this.timeOffset;
  }

  // Current world-space center of a part (movers oscillate).
  partCenter(part, out) {
    out = out || new THREE.Vector3();
    if (part.type === 'mover') {
      const t = (this.serverNow() / 1000) / part.period % 2;
      const tri = t < 1 ? t : 2 - t;
      out.set(part.x + part.dx * tri, part.y + part.dy * tri, part.z + part.dz * tri);
    } else {
      out.set(part.x, part.y, part.z);
    }
    return out;
  }

  // animate coins, movers, decorations and clouds each frame
  tick(dt, hiddenCoins) {
    const now = this.serverNow();
    const t = now / 1000;
    const v = new THREE.Vector3();
    for (const [id, mesh] of this.meshes) {
      const p = mesh.userData.part;
      if (p.type === 'coin') {
        mesh.rotation.y = t * 2.4;
        const hidden = hiddenCoins && hiddenCoins.has(id);
        mesh.visible = !hidden;
        if (!hidden) mesh.position.y = p.y + Math.sin(t * 2 + p.x) * 0.18;
      } else if (p.type === 'mover') {
        this.partCenter(p, v);
        mesh.position.copy(v);
      }
      if (mesh.userData.animFn) mesh.userData.animFn(t, dt);
    }
    for (const c of this.clouds.children) {
      c.position.x += c.userData.speed * dt;
      if (c.position.x > 230) c.position.x = -230;
    }
  }

  spawnPoint() {
    const spawns = [...this.parts.values()].filter((p) => p.type === 'spawn');
    if (!spawns.length) return new THREE.Vector3(0, 6, 0);
    const s = spawns[Math.floor(Math.random() * spawns.length)];
    return new THREE.Vector3(s.x, s.y + s.sy / 2 + 2.2, s.z);
  }

  telePartner(part) {
    for (const p of this.parts.values()) {
      if (p.type === 'tele' && p.channel === part.channel && p.id !== part.id) return p;
    }
    return null;
  }
}
